CIB_MODS.register('card-statistics-mod', {
  meta: {
    name: 'Card Statistics Mod',
    creator: 'jxburros',
    version: '1.0.0',
    type: 'Plugin'
  },
  onAppInit(ctx) {
    console.log('[CardStatisticsMod] Initialized');
    ctx.api.showToast('Card Statistics Mod loaded', 'success');

    // Add a global statistics button to the header
    setTimeout(() => {
      const header = document.querySelector('.header-inner');
      if (header && !document.getElementById('statsBtn')) {
        const statsBtn = document.createElement('button');
        statsBtn.id = 'statsBtn';
        statsBtn.className = 'header-btn';
        statsBtn.title = 'View Statistics';
        statsBtn.textContent = '📊';
        statsBtn.onclick = () => {
          showGlobalStatistics(ctx);
        };
        const spacer = header.querySelector('.spacer');
        if (spacer) {
          header.insertBefore(statsBtn, spacer.nextSibling);
        }
      }
    }, 100);
  },
  onCardRender(ctx, cardId, cardElement) {
    const card = ctx.api.getCard(cardId);
    if (!card) return;

    // Calculate card statistics
    const stats = calculateCardStats(card, ctx);

    // Create stats panel
    const statsPanel = document.createElement('div');
    statsPanel.className = 'card-stats-panel';
    statsPanel.innerHTML = `
      <div class="card-stats-title">📊 Card Statistics</div>
      <div class="card-stats-grid">
        <div class="card-stat-item">
          <div class="card-stat-label">Words</div>
          <div class="card-stat-value">${stats.wordCount}</div>
        </div>
        <div class="card-stat-item">
          <div class="card-stat-label">Characters</div>
          <div class="card-stat-value">${stats.charCount}</div>
        </div>
        <div class="card-stat-item">
          <div class="card-stat-label">Children</div>
          <div class="card-stat-value">${stats.childCount}</div>
        </div>
        <div class="card-stat-item">
          <div class="card-stat-label">Descendants</div>
          <div class="card-stat-value">${stats.descendantCount}</div>
        </div>
        <div class="card-stat-item">
          <div class="card-stat-label">Max Depth</div>
          <div class="card-stat-value">${stats.maxDepth}</div>
        </div>
        <div class="card-stat-item">
          <div class="card-stat-label">Total Words</div>
          <div class="card-stat-value">${stats.totalWords}</div>
        </div>
      </div>
    `;

    // Add to card element
    const detailSection = cardElement.querySelector('.card-detail, .card-body');
    if (detailSection) {
      detailSection.appendChild(statsPanel);
    }
  }
});

function calculateCardStats(card, ctx) {
  const wordCount = card.body ? card.body.trim().split(/\s+/).filter(w => w.length > 0).length : 0;
  const charCount = card.body ? card.body.length : 0;
  const childCount = card.children ? card.children.length : 0;

  // Calculate descendants and depth
  let descendantCount = 0;
  let maxDepth = 0;
  let totalWords = wordCount;

  function countDescendants(cardId, depth) {
    const c = ctx.api.getCard(cardId);
    if (!c || !c.children) return;

    descendantCount += c.children.length;
    maxDepth = Math.max(maxDepth, depth);

    c.children.forEach(childId => {
      const child = ctx.api.getCard(childId);
      if (child && child.body) {
        const words = child.body.trim().split(/\s+/).filter(w => w.length > 0).length;
        totalWords += words;
      }
      countDescendants(childId, depth + 1);
    });
  }

  if (card.children && card.children.length > 0) {
    countDescendants(card.id, 1);
  }

  return {
    wordCount,
    charCount,
    childCount,
    descendantCount,
    maxDepth,
    totalWords
  };
}

function showGlobalStatistics(ctx) {
  const allCards = ctx.api.listCards();

  let totalCards = allCards.length;
  let totalWords = 0;
  let totalChars = 0;
  let maxDepth = 0;
  const tagCounts = {};

  allCards.forEach(card => {
    if (card.body) {
      const words = card.body.trim().split(/\s+/).filter(w => w.length > 0).length;
      totalWords += words;
      totalChars += card.body.length;
    }

    if (card.tags && Array.isArray(card.tags)) {
      card.tags.forEach(tag => {
        tagCounts[tag] = (tagCounts[tag] || 0) + 1;
      });
    }
  });

  // Calculate hierarchy depth
  function getDepth(cardId, depth = 0) {
    const card = ctx.api.getCard(cardId);
    if (!card || !card.children || card.children.length === 0) {
      return depth;
    }
    return Math.max(...card.children.map(childId => getDepth(childId, depth + 1)));
  }

  const rootIds = ctx.api.listRootIds();
  rootIds.forEach(rootId => {
    const depth = getDepth(rootId, 0);
    maxDepth = Math.max(maxDepth, depth);
  });

  const avgWordsPerCard = totalCards > 0 ? (totalWords / totalCards).toFixed(1) : 0;
  const topTags = Object.entries(tagCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([tag, count]) => `${tag} (${count})`)
    .join(', ') || 'None';

  // Create modal
  const modal = document.createElement('div');
  modal.className = 'modal-overlay show';
  modal.style.cssText = 'position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.7); display: flex; align-items: center; justify-content: center; z-index: 1000;';

  modal.innerHTML = `
    <div class="modal" style="max-width: 600px; background: var(--surface); border: 1px solid var(--border); padding: var(--space-2xl); border-radius: var(--radius);">
      <div class="modal-header" style="display: flex; justify-content: space-between; align-items: center; margin-bottom: var(--space-2xl);">
        <div class="modal-title" style="font-size: var(--text-xl); font-weight: 700;">📊 Global Statistics</div>
        <button class="modal-close" style="background: none; border: none; font-size: var(--text-xl); cursor: pointer; color: var(--text);">✕</button>
      </div>
      <div class="modal-body">
        <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-lg); margin-bottom: var(--space-2xl);">
          <div class="stat-box">
            <div style="font-size: var(--text-3xl); font-weight: 700; color: var(--text);">${totalCards}</div>
            <div style="font-size: var(--text-sm); color: var(--text-muted);">Total Cards</div>
          </div>
          <div class="stat-box">
            <div style="font-size: var(--text-3xl); font-weight: 700; color: var(--text);">${totalWords.toLocaleString()}</div>
            <div style="font-size: var(--text-sm); color: var(--text-muted);">Total Words</div>
          </div>
          <div class="stat-box">
            <div style="font-size: var(--text-3xl); font-weight: 700; color: var(--text);">${totalChars.toLocaleString()}</div>
            <div style="font-size: var(--text-sm); color: var(--text-muted);">Total Characters</div>
          </div>
          <div class="stat-box">
            <div style="font-size: var(--text-3xl); font-weight: 700; color: var(--text);">${avgWordsPerCard}</div>
            <div style="font-size: var(--text-sm); color: var(--text-muted);">Avg Words/Card</div>
          </div>
          <div class="stat-box">
            <div style="font-size: var(--text-3xl); font-weight: 700; color: var(--text);">${maxDepth}</div>
            <div style="font-size: var(--text-sm); color: var(--text-muted);">Max Hierarchy Depth</div>
          </div>
          <div class="stat-box">
            <div style="font-size: var(--text-3xl); font-weight: 700; color: var(--text);">${rootIds.length}</div>
            <div style="font-size: var(--text-sm); color: var(--text-muted);">Root Cards</div>
          </div>
        </div>
        <div style="border-top: 1px solid var(--border); padding-top: var(--space-lg);">
          <div style="font-weight: 700; margin-bottom: var(--space-sm);">Top Tags:</div>
          <div style="color: var(--text-muted); font-size: var(--text-sm);">${topTags}</div>
        </div>
      </div>
    </div>
  `;

  modal.querySelector('.modal-close').onclick = () => modal.remove();
  modal.onclick = (e) => {
    if (e.target === modal) modal.remove();
  };

  document.body.appendChild(modal);
}

